import{_ as t,o as i,c as o,ag as r}from"./chunks/framework.ePeAWSvT.js";const f=JSON.parse('{"title":"Firefox Certificate Setup","description":"","frontmatter":{},"headers":[],"relativePath":"certificate/firefox.md","filePath":"certificate/firefox.md","lastUpdated":1772297611000}'),s={name:"certificate/firefox.md"};function a(n,e,l,c,d,h){return i(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="firefox-certificate-setup" tabindex="-1">Firefox Certificate Setup <a class="header-anchor" href="#firefox-certificate-setup" aria-label="Permalink to &quot;Firefox Certificate Setup&quot;">​</a></h1><p>Firefox uses its own built-in certificate store (NSS) rather than the operating system&#39;s trust store. This means that even if you have installed the NectoProxy CA certificate at the system level (macOS Keychain, Windows Certificate Store, or Linux system CA directory), Firefox will not automatically trust it.</p><p>You have two options: import the certificate directly into Firefox, or configure Firefox to use system certificates.</p><h2 id="method-1-import-into-firefox-recommended" tabindex="-1">Method 1: Import into Firefox (Recommended) <a class="header-anchor" href="#method-1-import-into-firefox-recommended" aria-label="Permalink to &quot;Method 1: Import into Firefox (Recommended)&quot;">​</a></h2><p>This method adds the NectoProxy CA certificate directly to Firefox&#39;s internal certificate manager.</p><ol><li><p><strong>Open Firefox Settings</strong></p><ul><li>Click the hamburger menu (three horizontal lines) in the top-right corner.</li><li>Select <strong>Settings</strong> (or <strong>Preferences</strong> on some systems).</li><li>Alternatively, type <code>about:preferences</code> in the address bar and press Enter.</li></ul></li><li><p><strong>Navigate to Certificates</strong></p><ul><li>In the left sidebar, click <strong>Privacy &amp; Security</strong>.</li><li>Scroll down to the <strong>Certificates</strong> section (near the bottom of the page).</li><li>Click the <strong>View Certificates</strong> button.</li></ul></li><li><p><strong>Import the CA Certificate</strong></p><ul><li>In the Certificate Manager dialog, click the <strong>Authorities</strong> tab.</li><li>Click the <strong>Import</strong> button.</li><li>Navigate to <code>~/.nectoproxy/certs/</code> (on macOS/Linux) or <code>%USERPROFILE%\\.nectoproxy\\certs\\</code> (on Windows).</li><li>Select the <code>ca.pem</code> file and click <strong>Open</strong>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Finding the Certificate File</p><p>If you cannot navigate to the <code>.nectoproxy</code> directory (hidden directories may not be visible in the file picker), you can:</p><ul><li>On macOS/Linux: Type <code>~/.nectoproxy/certs/ca.pem</code> directly in the file picker&#39;s path bar, or press <code>Cmd+Shift+.</code> (macOS) to show hidden files.</li><li>On Windows: Type <code>%USERPROFILE%\\.nectoproxy\\certs\\ca.pem</code> in the file name field.</li><li>Or copy the certificate to a visible location first: <code>cp ~/.nectoproxy/certs/ca.pem ~/Desktop/nectoproxy-ca.pem</code></li></ul></div></li><li><p><strong>Set Trust Settings</strong></p><ul><li>A dialog appears asking how you want to trust this certificate.</li><li>Check <strong>Trust this CA to identify websites</strong>.</li><li>You do not need to check &quot;Trust this CA to identify email users&quot; for proxy usage.</li><li>Click <strong>OK</strong>.</li></ul></li><li><p><strong>Confirm Import</strong></p><ul><li>The NectoProxy CA certificate should now appear in the Authorities list, grouped under its organization name.</li></ul></li></ol><h2 id="method-2-use-system-certificates" tabindex="-1">Method 2: Use System Certificates <a class="header-anchor" href="#method-2-use-system-certificates" aria-label="Permalink to &quot;Method 2: Use System Certificates&quot;">​</a></h2><p>Instead of importing the certificate manually, you can configure Firefox to trust all certificates in the operating system&#39;s trust store. This is useful if you have already installed the NectoProxy CA at the system level.</p><ol><li><p><strong>Open Firefox Configuration</strong></p><ul><li>Type <code>about:config</code> in the address bar and press Enter.</li><li>Click <strong>Accept the Risk and Continue</strong> when warned about advanced settings.</li></ul></li><li><p><strong>Search for the Setting</strong></p><ul><li>In the search bar, type: <code>security.enterprise_roots.enabled</code></li></ul></li><li><p><strong>Enable the Setting</strong></p><ul><li>If the value is <code>false</code>, click the toggle button to set it to <code>true</code>.</li><li>If the setting does not exist, click the <strong>+</strong> button to create it as a Boolean with the value <code>true</code>.</li></ul></li><li><p><strong>Restart Firefox</strong></p><ul><li>Close and reopen Firefox for the change to take effect.</li></ul></li></ol><div class="warning custom-block"><p class="custom-block-title">Limitations of Method 2</p><ul><li>This method relies on the NectoProxy CA being installed in the system trust store first (see <a href="/certificate/macos.html">macOS</a>, <a href="/certificate/windows.html">Windows</a>, or <a href="/certificate/linux.html">Linux</a> guides).</li><li>On Linux, this feature reads from the system NSS database or the p11-kit trust store, depending on the distribution. It may not work on all distributions.</li><li>This setting causes Firefox to trust <strong>all</strong> system root certificates, not just NectoProxy&#39;s. If you prefer fine-grained control, use Method 1.</li></ul></div><h2 id="verify-installation" tabindex="-1">Verify Installation <a class="header-anchor" href="#verify-installation" aria-label="Permalink to &quot;Verify Installation&quot;">​</a></h2><p>After installing the certificate using either method:</p><ol><li><p>Make sure your Firefox proxy is set to <code>127.0.0.1:8888</code>:</p><ul><li>Go to Settings &gt; General &gt; Network Settings &gt; Settings.</li><li>Select <strong>Manual proxy configuration</strong>.</li><li>Set HTTP Proxy to <code>127.0.0.1</code> and Port to <code>8888</code>.</li><li>Check <strong>Also use this proxy for HTTPS</strong>.</li><li>Click <strong>OK</strong>.</li></ul></li><li><p>Navigate to any HTTPS website (e.g., <code>https://example.com</code>).</p></li><li><p>The page should load without certificate warnings.</p></li><li><p>Click the lock icon in the address bar and select <strong>Connection secure &gt; More information &gt; View Certificate</strong> to confirm the certificate chain includes the NectoProxy CA.</p></li></ol><h2 id="removing-the-certificate" tabindex="-1">Removing the Certificate <a class="header-anchor" href="#removing-the-certificate" aria-label="Permalink to &quot;Removing the Certificate&quot;">​</a></h2><h3 id="if-imported-via-method-1" tabindex="-1">If Imported via Method 1 <a class="header-anchor" href="#if-imported-via-method-1" aria-label="Permalink to &quot;If Imported via Method 1&quot;">​</a></h3><ol><li>Open Firefox Settings &gt; Privacy &amp; Security &gt; View Certificates.</li><li>Go to the <strong>Authorities</strong> tab.</li><li>Find the NectoProxy CA certificate in the list.</li><li>Select it and click <strong>Delete or Distrust</strong>.</li><li>Confirm the removal.</li></ol><h3 id="if-using-method-2" tabindex="-1">If Using Method 2 <a class="header-anchor" href="#if-using-method-2" aria-label="Permalink to &quot;If Using Method 2&quot;">​</a></h3><ol><li>Navigate to <code>about:config</code>.</li><li>Search for <code>security.enterprise_roots.enabled</code>.</li><li>Toggle it back to <code>false</code>.</li><li>Restart Firefox.</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="certificate-import-fails" tabindex="-1">Certificate Import Fails <a class="header-anchor" href="#certificate-import-fails" aria-label="Permalink to &quot;Certificate Import Fails&quot;">​</a></h3><ul><li><strong>File format</strong>: Firefox expects PEM-encoded certificates. The NectoProxy <code>ca.pem</code> file is already in PEM format. If import fails, verify the file is not corrupted by checking it starts with <code>-----BEGIN CERTIFICATE-----</code>.</li><li><strong>File permissions</strong>: Ensure the certificate file is readable. Run <code>chmod 644 ~/.nectoproxy/certs/ca.pem</code> if needed.</li></ul><h3 id="https-sites-still-show-warnings-after-import" tabindex="-1">HTTPS Sites Still Show Warnings After Import <a class="header-anchor" href="#https-sites-still-show-warnings-after-import" aria-label="Permalink to &quot;HTTPS Sites Still Show Warnings After Import&quot;">​</a></h3><ul><li><strong>Restart Firefox</strong>: Fully close and reopen Firefox (check that no Firefox processes are running in the background).</li><li><strong>Check proxy settings</strong>: Verify that Firefox is actually routing through the NectoProxy proxy. Visit <code>http://httpbin.org/ip</code> and check if the request appears in the NectoProxy Web UI.</li><li><strong>Verify trust settings</strong>: Open the Certificate Manager, go to the Authorities tab, find the NectoProxy CA, and click <strong>Edit Trust</strong>. Ensure &quot;Trust this CA to identify websites&quot; is checked.</li></ul><h3 id="firefox-for-android" tabindex="-1">Firefox for Android <a class="header-anchor" href="#firefox-for-android" aria-label="Permalink to &quot;Firefox for Android&quot;">​</a></h3><p>Firefox on Android also uses its own certificate store. You need to import the certificate through Firefox&#39;s settings:</p><ol><li>Transfer the <code>ca.pem</code> file to your Android device.</li><li>Open Firefox on Android.</li><li>Go to Settings &gt; About Firefox &gt; tap the Firefox logo 5 times to enable secret settings.</li><li>Look for certificate management options in the advanced settings.</li></ol><p>Alternatively, use the <code>security.enterprise_roots.enabled</code> method if the certificate is already installed at the Android system level.</p><details class="details custom-block"><summary>Enterprise Deployment</summary><p>For organizations deploying NectoProxy across many machines, you can distribute the Firefox configuration via enterprise policies. Create a <code>policies.json</code> file:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;policies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Certificates&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;ImportEnterpriseRoots&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Place this file in Firefox&#39;s distribution directory:</p><ul><li><strong>macOS</strong>: <code>/Applications/Firefox.app/Contents/Resources/distribution/policies.json</code></li><li><strong>Linux</strong>: <code>/usr/lib/firefox/distribution/policies.json</code> or <code>/usr/lib64/firefox/distribution/policies.json</code></li><li><strong>Windows</strong>: <code>C:\\Program Files\\Mozilla Firefox\\distribution\\policies.json</code></li></ul><p>This automatically enables <code>security.enterprise_roots.enabled</code> for all users.</p></details>`,28)])])}const u=t(s,[["render",a]]);export{f as __pageData,u as default};
